package com.kartyavya.report.service; import com.fasterxml.jackson.databind.ObjectMapper; import com.kartyavya.contracts.IntegrationEvent; import com.kartyavya.report.entity.OutboxEvent; import com.kartyavya.report.repository.OutboxRepository; import org.springframework.stereotype.Service; import java.util.UUID; @Service public class OutboxService{private final OutboxRepository repo;private final ObjectMapper json;public OutboxService(OutboxRepository r,ObjectMapper j){repo=r;json=j;}public void enqueue(String type,String correlation,Object data){try{OutboxEvent e=new OutboxEvent();e.setId(UUID.randomUUID().toString());e.setEventType(type);e.setRoutingKey(type);e.setPayload(json.writeValueAsString(IntegrationEvent.of(type,correlation,data)));repo.save(e);}catch(Exception e){throw new IllegalStateException("Unable to create integration event",e);}}}
